```javascript
// Importer Discord.js et les modules requis
const { Client, GatewayIntentBits } = require('discord.js');

// Créer une instance du client Discord
const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent,
  ],
});

// Connexion du client au Discord
client.once('ready', () => {
  console.log('Bot Discord prêt !');
});

// Écouteur pour les commandes slash
client.on('interactionCreate', async interaction => {
  if (!interaction.isCommand()) return;

  // Commande "ban"
  if (interaction.commandName === 'ban') {
    if (!interaction.memberPermissions.has('BAN_MEMBERS')) {
      return interaction.reply({
        content: 'Vous n'avez pas la permission de bannir les utilisateurs !',
        ephemeral: true,
      });
    }

    if (!interaction.options.getUser('user')) {
      return interaction.reply({
        content: 'Veuillez spécifier un utilisateur à bannir !',
        ephemeral: true,
      });
    }

    const user = interaction.options.getUser('user');
    const reason = interaction.options.getString('reason') || 'Aucune raison fournie';

    try {
      await interaction.guild.members.ban(user, { days: 0, reason });

      return interaction.reply({
        content: `**${user.tag}** a été banni avec la raison : ${reason}`,
        ephemeral: true,
      });
    } catch (error) {
      console.error(error);
      return interaction.reply({
        content: 'Une erreur est survenue lors du bannissement de l\'utilisateur !',
        ephemeral: true,
      });
    }
  }
});

// Se connecter au Discord avec la clé API du bot
client.login('VotreCléAPI');
