Voici un cadre de test de haute qualité dans Cypress qui utilise Docker et utilise également la capacité de Cypress à capturer des captures d'écran et à les enregistrer :

```typescript
// cypress.config.ts

import { defineConfig } from 'cypress'

export default defineConfig({
  e2e: {
    setupNodeEvents(on, config) {
      // Set up Cypress to use Docker for testing
      require('cypress-docker-test/run', { config })

      // Set up Cypress to capture screenshots and videos
      on('before:spec', (spec, options) => {
        Cypress.config('video', true)
        Cypress.config('screenRecord', {
          path: 'screenshots',
          full: true,
          preserveAspectRatio: true,
          clip: undefined,
          quality: 0.8,
        })
      })

      // Set up Cypress to automatically retry failed tests
      on('task', { retryTest: (command, ...args) => Cypress.Promise.try(() => command(...args)).then(result => {
        if (result && result.status === 'failed') {
          return Cypress.Promise.reject(new Error(`Test failed. Retrying...`))
        }

        return result
      }) })

      // Set up Cypress to automatically wait for network requests to complete
      on('task', { waitOnRequest: (req) => {
        return new Cypress.Promise((resolve, reject) => {
          req.on('success', () => {
            resolve()
          })

          req.on('error', () => {
            reject(new Error(`Network request failed: ${req.method} ${req.url}`))
          })
        })
      }})

      // Set up Cypress to automatically retry failed network requests
      on('task', { retryNetworkRequest: (req) => Cypress.Promise.try(() => req).then(result => {
        if (result && result.status === 'failed') {
          return Cypress.Promise.reject(new Error(`Network request failed: ${req.method} ${req.url}. Retrying...`))
        }

        return result
      }) })

      // Set up Cypress to automatically wait for animations to complete
      on('task', { waitAnimations: () => Cypress.Promise.try(() => {
        const animations = document.querySelectorAll('*, ::before, ::after')
        return new Cypress.Promise(resolve => {
          animations.forEach(animation => {
            animation.addEventListener('animationend', () => {
              animation.removeEventListener('animationend', animationEnd)
              resolve()
            })

            const animationEnd = () => {
              animation.removeEventListener('animationend', animationEnd)
              resolve()
            }

            animation.addEventListener('transitionend', () => {
              animation.removeEventListener('transitionend', transitionEnd)
              resolve()
            })

            const transitionEnd = () => {
              animation.removeEventListener('transitionend', transitionEnd)
              resolve()
            }
          })
        })
      }) })

      return config
    },
  },
})
```

With this configuration, Cypress will:

1. Use Docker for testing
2. Capture screenshots and videos automatically
3. Automatically retry failed tests
4. Automatically wait for network requests to complete
5. Automatically retry failed network requests
6. Automatically wait for animations to complete

