Voici une fonction C++ qui prend une référence à un std::string contenant du texte au format markdown et renvoie un std::string contenant du texte au format HTML :

```cpp
#include <iostream>
#include <string>
#include <regex>

// Fonction de conversion de Markdown vers HTML
std::string convertMarkdownToHTML(std::string& markdown) {
    // Regroupement des expressions régulières de conversion
    std::string html = markdown;
    std::regex italicize_regex("_(.+?)_");
    std::regex bold_regex("__(.+?)__");
    std::regex link_regex("\\[\\[(.+?)\\]\\]\\((.+?)\\)");
    std::regex header_regex("^#{1,6}(.+?) #*$");

    // Remplacement des expressions régulières de conversion
    html = std::regex_replace(html, italicize_regex, "<em>$1</em>");
    html = std::regex_replace(html, bold_regex, "<strong>$1</strong>");
    std::smatch match;
    while (std::regex_search(html, match, link_regex)) {
        std::string link_text = match[1];
        std::string link_url = match[2];
        html = std::regex_replace(html, match, "<a href=\"" + link_url + "\">" + link_text + "</a>");
        html = std::regex_replace(html, std::regex("\\[\\[(.+?)\\]\\]", std::regex::match_flag_type::match_not_null), "");
    }
    std::regex header_regex2("^#{1,6}(.+?)$");
    while (std::regex_search(html, match, header_regex2)) {
        std::string header_text = match[1];
        std::string header_level = std::to_string(match.position(0).length() / 2);
        html = std::regex_replace(html, match, "<h" + header_level + ">" + header_text + "</h" + header_level + ">");
        html = std::regex_replace(html, std::regex("^#{1,6}", std::regex::match_flag_type::match_not_null), "");
    }

    return html;
}

int main() {
    std::string markdown = "Hello, _world_! This is a **bold** and *italic* text. [Link](https://example.com) to an external site. # Header 1\n## Header 2\n### Header 3\n#### Header 4\n##### Header 5\n###### Header 6";
    std::string html = convertMarkdownToHTML(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

Cette fonction utilise des expressions régulières pour détecter les balises Markdown correspondantes (italique, gras, lien et en-tête) et les remplacer par leurs équivalents HTML. Vous pouvez ensuite appeler cette fonction en passant en argument un std::string contenant du texte au format Markdown, et elle renvoie un std::string contenant le texte converti au format HTML. L'exemple de fonction ci-dessus est conçu pour illustrer le principe de base de la conversion, mais il ne couvre pas toutes les possibilités de Markdown. Pour une implémentation plus complète, vous pourriez considérer d'utiliser une bibliothèque de conversion de Markdown, telle que Pugl, Fmt, ou MarkdownSharp.

