Voici un code de base en C pour créer le serpent en utilisant SDL2 :

```c
#include <stdio.h>
#include <stdlib.h>
#include <SDL2/SDL.h>
#include <SDL2/SDL_image.h>

#define WINDOW_WIDTH 800
#define WINDOW_HEIGHT 600

// Structure du serpent
typedef struct Snake {
    int x[100], y[100];
    int length;
    int direction;
} Snake;

// Chargement des images
SDL_Texture *snakeTexture;
SDL_Texture *appleTexture;
SDL_Texture *backgroundTexture;

// Fonction de dessin
void drawScene(SDL_Renderer *renderer) {
    SDL_RenderCopy(renderer, backgroundTexture, NULL, NULL);
    for (int I = 0; I < snake.length; i++) {
        SDL_Rect source = {0, 0, 20, 20};
        SDL_Rect dest = {snake.x[i], snake.y[i], 20, 20};
        SDL_RenderCopy(renderer, snakeTexture, &source, &dest);
    }
    SDL_Rect appleRect = {appleX, appleY, 20, 20};
    SDL_RenderCopy(renderer, appleTexture, NULL, &appleRect);
}

// Fonction de gestion d'événements
void eventHandler(SDL_Event *event, Snake *snake) {
    switch (event->type) {
        case SDL_KEYDOWN:
            switch (event->key.keysym.sym) {
                case SDLK_LEFT:
                    if (snake->direction != SDL_SCANCODE_RIGHT)
                        snake->direction = SDL_SCANCODE_LEFT;
                    break;
                case SDLK_RIGHT:
                    if (snake->direction != SDL_SCANCODE_LEFT)
                        snake->direction = SDL_SCANCODE_RIGHT;
                    break;
                case SDLK_UP:
                    if (snake->direction != SDL_SCANCODE_DOWN)
                        snake->direction = SDL_SCANCODE_UP;
                    break;
                case SDLK_DOWN:
                    if (snake->direction != SDL_SCANCODE_UP)
                        snake->direction = SDL_SCANCODE_DOWN;
                    break;
            }
            break;
    }
}

// Fonction de comportement du serpent
void moveSnake(Snake *snake) {
    for (int I = snake->length - 1; I > 0; i--) {
        snake->x[i] = snake->x[i - 1];
        snake->y[i] = snake->y[i - 1];
    }
    switch (snake->direction) {
        case SDL_SCANCODE_LEFT:
            snake->x[0]--;
            break;
        case SDL_SCANCODE_RIGHT:
            snake->x[0]++;
            break;
        case SDL_SCANCODE_UP:
            snake->y[0]--;
            break;
        case SDL_SCANCODE_DOWN:
            snake->y[0]++;
            break;
    }
}

// Fonction de génération de niveau
void generateLevel(Snake *snake) {
    int maxX = WINDOW_WIDTH / 20;
    int maxY = WINDOW_HEIGHT / 20;
    int appleX = rand() % maxX;
    int appleY = rand() % maxY;
    while (isPointInSnake(appleX, appleY, snake)) {
        appleX = rand() % maxX;
        appleY = rand() % maxY;
    }
    snake->x[snake->length] = appleX * 20;
    snake->y[snake->length] = appleY * 20;
}

// Fonction de vérification de collision avec la pomme
int isAppleCollision(int appleX, int appleY, Snake *snake) {
    for (int I = 0; I < snake->length; i++) {
        if (snake->x[i] == appleX && snake->y[i] == appleY)
            return 1;
    }
    return 0;
}

// Fonction de vérification de collision avec le serpent
int isPointInSnake(int x, int y, Snake *snake) {
    for (int I = 0; I < snake->length; i++) {
        if (snake->x[i] == x && snake->y[i] == y)
            return 1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    SDL_Init(SDL_INIT_EVERYTHING);
    IMG_Init(IMG_INIT_PNG);

    SDL_Window *window = SDL_CreateWindow(
        "Snake Game",
        SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED,
        WINDOW_WIDTH, WINDOW_HEIGHT,
        SDL_WINDOW_SHOWN
    );

    SDL_Renderer *renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);

    // Charger les images
    snakeTexture = IMG_LoadTexture(renderer, "snake.png");
    appleTexture = IMG_LoadTexture(renderer, "apple.png");
    backgroundTexture = IMG_LoadTexture(renderer, "background.png");

    Snake snake = {0};
    snake.length = 1;
    snake.x[0] = WINDOW_WIDTH / 2;
    snake.y[0] = WINDOW_HEIGHT / 2;
    snake.direction = SDL_SCANCODE_RIGHT;

    int appleX, appleY;

    while (1) {
        SDL_Event event;
        while (SDL_PollEvent(&event)) {
            eventHandler(&event, &snake);
            if (event.type == SDL_QUIT)
                break;
        }

        moveSnake(&snake);
        appleX = snake.x[snake.length];
        appleY = snake.y[snake.length];
        generateLevel(&snake);

        if (isAppleCollision(appleX, appleY, &snake)) {
            snake.length++;
        }

        SDL_RenderClear(renderer);
        drawScene(renderer);
        SDL_RenderPresent(renderer);

        SDL_Delay(10);
    }

    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    SDL_Quit();
    return 0;
}
```

