Voici une fonction en JavaScript qui vérifie si un des nombres d'un tableau de 5 nombres est premier et imprime le nombre sur la console si c'est le cas :

```javascript
function checkPrime(arr) {
  for (let I = 0; I < arr.length; i++) {
    const num = arr[i];
    if (isPrime(num)) {
      console.log(num);
      return;
    }
  }
}

function isPrime(n) {
  if (n < 2) {
    return false;
  }
  for (let I = 2; I <= Math.sqrt(n); i++) {
    if (n % I === 0) {
      return false;
    }
  }
  return true;
}

// Exemple d'utilisation
