Voici un programme C++ qui lit un fichier texte ligne par ligne et compte le nombre d'occurrences d'un mot spécifique dans le fichier :

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>

int main() {
    std::string filename;
    std::string word;

    // Demander le nom du fichier à lire
    std::cout << "Enter the name of the file to read: ";
    std::cin >> filename;

    // Demander le mot à chercher
    std::cout << "Enter the word to search for: ";
    std::cin >> word;

    // Ouvrir le fichier pour lecture
    std::ifstream file(filename);
    if (!file) {
        std::cerr << "Error: Unable to open file " << filename << std::endl;
        return 1;
    }

    // Initialiser le compteur de mots
    unsigned int count = 0;

    // Lire chaque ligne du fichier
    std::string line;
    while (std::getline(file, line)) {
        // Convertir la ligne en chaîne de caractères sans espaces ni caractères de ponctuation
        std::string cleaned_line = line;
        cleaned_line.erase(std::remove_if(cleaned_line.begin(), cleaned_line.end(), [](char c) {
            return !std::isalnum(c) && c != '_';
        }), cleaned_line.end());
        std::transform(cleaned_line.begin(), cleaned_line.end(), cleaned_line.begin(), ::tolower);

        // Vérifier si le mot à chercher est présent dans la ligne
        if (std::find(cleaned_line.begin(), cleaned_line.end(), word) != cleaned_line.end()) {
            count++; // Augmenter le compteur de mots
        }
    }

    // Fermer le fichier
    file.close();

    // Afficher le résultat
    std::cout << "The word '" << word << "' appears " << count << " times in the file " << filename << std::endl;

    return 0;
}
```

